'use strict';
globalThis.RobotPapers=(()=>{
 const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const $=id=>document.getElementById(id),data=()=>globalThis.ATLAS_ROBOT_PAPERS;
 let state={track:'all',query:'',sort:'newest'};
 const target=p=>`#guide?id=${encodeURIComponent(p.guideId)}&section=${p.section||'reading-'+p.lessonId}`;
 function bodyText(p){const k=globalThis.ATLAS_GUIDES?.find(g=>g.id===p.guideId)?.knowledge;const x=[...(k?.readings?.lessons||[]),...(k?.rl?.lessons||[])].find(x=>x.id===p.lessonId);return x?JSON.stringify([x.sections,x.specs,x.pipeline]):'';}
 function select(papers,filters){return papers.filter(p=>(filters.track==='all'||p.track===filters.track)&&(!filters.query.trim()||filters.query.toLowerCase().trim().split(/\s+/).every(q=>[p.title,p.question,p.change,p.detail,...p.prerequisites,bodyText(p)].join(' ').toLowerCase().includes(q)))).sort((a,b)=>filters.sort==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));}
 function figure(p){const k=globalThis.ATLAS_GUIDES.find(g=>g.id===p.guideId)?.knowledge;return k?.figures.find(f=>f.id===p.figureId);}
 function card(p){const f=figure(p),track=data().tracks.find(t=>t.id===p.track);return `<article class="robot-paper-card"><a href="${target(p)}" class="robot-paper-image">${f?`<img src="${h(f.src)}" alt="${h(f.alt)}" width="${f.width}" height="${f.height}" loading="lazy">`:`<div class="robot-paper-concept"><span>${h(p.question)}</span><b>${h(p.title)}</b></div>`}<span class="robot-paper-image-label">${f?'原论文 · '+h(f.figure):'方法精读'} ↗</span></a><div class="robot-paper-content"><div class="robot-paper-meta"><time datetime="${h(p.date)}">${h(p.date)}</time><span>${h(track?.title)}</span></div><h3><a href="${target(p)}">${h(p.title)} <span>↗</span></a></h3><p class="robot-paper-question">${h(p.question)}</p><dl><div><dt>方法推进</dt><dd>${h(p.change)}</dd></div><div><dt>重点拆解</dt><dd>${h(p.detail)}</dd></div></dl><div class="robot-paper-prereqs">先认识 ${p.prerequisites.map(x=>`<span>${h(x)}</span>`).join('')}</div><a class="robot-reading-link" href="${target(p)}">展开站内精读 <span>→</span></a></div></article>`;}
 function lanes(){return `<div class="robot-lanes">${data().tracks.map(t=>`<article class="robot-lane"><div><span>${h(t.kicker)}</span><h3>${h(t.title)}</h3><p>${h(t.description)}</p></div><ol>${t.milestones.map(id=>data().papers.find(p=>p.id===id)).filter(Boolean).map(p=>`<li><a href="${target(p)}"><time>${h(p.year)}</time><b>${h(p.title)}</b><small>${h(p.change)}</small></a></li>`).join('')}</ol></article>`).join('')}</div>`;}
 function controlFocus(id){const item=data().controlFocus?.find(x=>x.id===id);if(!item)return;const p=data().papers.find(p=>p.id===id);const row=(label,items,kind)=>`<div class="control-flow ${kind}"><h4>${label}</h4><ol>${items.map(s=>`<li><b>${h(s.label)}</b><span>${h(s.text)}</span></li>`).join('')}</ol></div>`;$('robot-control-panel').innerHTML=`<div class="control-focus-title"><div><span>${h(item.dateLabel)}</span><h3>${h(item.question)}</h3></div><a href="${target(p)}">读 ${h(p.title)} 精读 ↗</a></div>${row('训练时 · 从数据学到能力',item.training,'training')}${row('运行时 · 从观测生成动作',item.runtime,'runtime')}<div class="control-feedback"><span>↶ ${h(item.feedback)}</span></div><div class="control-focus-explain"><p><b>方法的关键</b>${h(item.meaning)}</p><p><b>PPO 在哪里</b>${h(item.ppo)}</p></div>`;document.querySelectorAll('[data-control-paper]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.controlPaper===id));}
 function renderList(){const list=select(data().papers,state);$('robot-paper-tabs').innerHTML=[{id:'all',title:'全部方向'},...data().tracks].map(t=>`<button type="button" data-robot-track="${h(t.id)}" aria-pressed="${state.track===t.id}" class="${state.track===t.id?'active':''}">${h(t.title)}</button>`).join('');$('robot-paper-count').textContent=`${list.length} 篇站内精读 · 来源核对 ${data().checked}`;$('robot-paper-results').innerHTML=list.length?list.map(card).join(''):'<div class="empty-state"><h3>没有匹配的论文</h3><p>试试“动作块”“点云”“PPO”或“标定”。</p><button type="button" data-robot-reset>查看全部论文</button></div>';}
 function sync(){const p=new URLSearchParams();if(state.track!=='all')p.set('track',state.track);if(state.query)p.set('query',state.query);if(state.sort!=='newest')p.set('sort',state.sort);history.replaceState(null,'','#robot-papers'+(p.size?'?'+p:''));renderList();}
 function render(params){const d=data();state={track:d.tracks.some(t=>t.id===params.get('track'))?params.get('track'):'all',query:params.get('query')||'',sort:params.get('sort')==='oldest'?'oldest':'newest'};$('robot-research-lanes').innerHTML=lanes();$('robot-paper-query').value=state.query;$('robot-paper-sort').value=state.sort;$('robot-control-tabs').innerHTML=(d.controlFocus||[]).map((x,i)=>`<button type="button" data-control-paper="${h(x.id)}" aria-pressed="${i===0}" aria-controls="robot-control-panel">${h(d.papers.find(p=>p.id===x.id).title.split(' · ')[0])}<span>${h(x.tag)}</span></button>`).join('');controlFocus(d.controlFocus?.[0]?.id);renderList();}
 function home(){const d=data();if(!d)return;const chosen=['sonic','latent','pi07'].map(id=>d.papers.find(p=>p.id===id)).filter(Boolean);$('home-robot-papers').innerHTML=chosen.map(card).join('');$('robot-paper-total').textContent=d.papers.length;}
 function guideLink(k){return ['embodied','robotics'].includes(k.category)?`<a class="robot-guide-return" href="#robot-papers">机器人论文精读 <span>标定 · 动作生成 · 通用策略 · 运动控制 →</span></a>`:'';}
 document.addEventListener('click',ev=>{const c=ev.target.closest('[data-control-paper]');if(c)controlFocus(c.dataset.controlPaper);const t=ev.target.closest('[data-robot-track]');if(t){state.track=data().tracks.some(x=>x.id===t.dataset.robotTrack)?t.dataset.robotTrack:'all';sync();}if(ev.target.closest('[data-robot-reset]')){state={track:'all',query:'',sort:'newest'};$('robot-paper-query').value='';$('robot-paper-sort').value='newest';sync();}});
 document.addEventListener('input',ev=>{if(ev.target.id==='robot-paper-query'){state.query=ev.target.value;sync();}});
 document.addEventListener('change',ev=>{if(ev.target.id==='robot-paper-sort'){state.sort=ev.target.value==='oldest'?'oldest':'newest';sync();}});
 return {render,home,select,target,guideLink};
})();
